mapper.select:
SELECT sku_id, spec_group_id, spec_value_id, spec_value, sort, create_time FROM product_sku_spec_rel WHERE sku_id IN
#{id}
ORDER BY sort ASC, spec_group_id ASC

mapper.delete:
DELETE r FROM product_sku_spec_rel r
JOIN product_sku s ON s.id = r.sku_id
WHERE s.product_id = #{productId}

mapper.select:
SELECT COUNT(*)
FROM product_sku s
WHERE s.product_id = #{productId}

      AND s.id NOT IN
      #{eid}

  AND (
    SELECT COUNT(*) FROM product_sku_spec_rel r WHERE r.sku_id = s.id
  ) = #{relPairs.size}
  AND NOT EXISTS (
    SELECT 1 FROM product_sku_spec_rel r
    WHERE r.sku_id = s.id
      AND NOT EXISTS (
        SELECT 1 FROM (VALUES

            (#{p.groupId}, #{p.valueId})

        ) AS wanted(gid, vid)
        WHERE wanted.gid = r.spec_group_id AND wanted.vid = r.spec_value_id
      )
  )
